CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE users (id uuid PRIMARY KEY, email text NOT NULL UNIQUE, name text NOT NULL, password_hash text NOT NULL, verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (id_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE organizations (id uuid PRIMARY KEY, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE workspaces (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,organization_id));
CREATE TABLE memberships (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), workspace_id uuid, user_id uuid NOT NULL REFERENCES users(id), role text NOT NULL CHECK(role IN ('owner','org_admin','workspace_admin','builder','operator','analyst','viewer')), FOREIGN KEY(workspace_id,organization_id) REFERENCES workspaces(id,organization_id), CHECK ((role IN ('owner','org_admin') AND workspace_id IS NULL) OR role NOT IN ('owner','org_admin')));
CREATE UNIQUE INDEX membership_scope ON memberships(organization_id,COALESCE(workspace_id,'00000000-0000-0000-0000-000000000000'),user_id);
CREATE TABLE invitations (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), workspace_id uuid, email text NOT NULL, role text NOT NULL CHECK(role IN ('org_admin','workspace_admin','builder','operator','analyst','viewer')), token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, accepted_at timestamptz, FOREIGN KEY(workspace_id,organization_id) REFERENCES workspaces(id,organization_id));
CREATE TABLE auth_tokens (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, purpose text NOT NULL CHECK(purpose IN ('verify','reset')), expires_at timestamptz NOT NULL);
CREATE TABLE secrets (id uuid PRIMARY KEY, organization_id uuid NOT NULL, workspace_id uuid NOT NULL, name text NOT NULL, ciphertext jsonb NOT NULL, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,name), FOREIGN KEY(workspace_id,organization_id) REFERENCES workspaces(id,organization_id));
CREATE TABLE audit_events (id uuid PRIMARY KEY, organization_id uuid REFERENCES organizations(id), workspace_id uuid, actor_id uuid NOT NULL REFERENCES users(id), action text NOT NULL, entity_id uuid, metadata jsonb NOT NULL DEFAULT '{}', ip text NOT NULL, user_agent text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,organization_id) REFERENCES workspaces(id,organization_id));
CREATE INDEX audit_tenant_time ON audit_events(organization_id,created_at DESC,id);
CREATE TABLE mail_outbox (id uuid PRIMARY KEY, recipient text NOT NULL, subject text NOT NULL, encrypted_body jsonb NOT NULL, sent_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
